import { automataContent } from '@mcthaydt/automata-content/vite'
import { previewHeaders } from '@mcthaydt/examples-runner/host/preview-headers'
import { defineConfig } from 'vite'
import { roomSchema } from './room.schema.ts'
import config from './ship.config.ts'

// automata-content compiles content/ when Vite starts and again on every save in dev, and serves the result as
// `virtual:automata/content`. The browser check points it at a copy of content/ (AF_DEMO_CONTENT_ROOT) so it
// can edit the room without touching this folder.
export default defineConfig({
  base: './',
  build: { outDir: 'dist', emptyOutDir: true },
  plugins: [automataContent({ root: process.env.AF_DEMO_CONTENT_ROOT, schemas: [roomSchema] })],
  preview: { headers: previewHeaders(config) },
})

import { defineConfig } from 'vitest/config'

// The room schema in Node: the compiler gets the base's message and the row it is about.
export default defineConfig({ test: { environment: 'node', include: ['*.test.ts'] } })

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { BODY_SPRITES } from './sprites.ts'

// The same palette gate as base-2d's art.test.ts: every color the demo draws is an Endesga 64 color, checked
// against the palette file exactly as the Owner supplied it.
const fromFile = readFileSync(
  new URL('../../../../docs/art/palettes/endesga-64.txt', import.meta.url),
  'utf8',
)
  .split(/\r?\n/)
  .filter((line) => line !== '' && !line.startsWith(';'))
  .map((line) => `#${line.slice(2).toLowerCase()}`)

describe('the body sprites', () => {
  it.each(Object.entries(BODY_SPRITES))('%s is an 8 × 8 rectangle of known palette keys', (_name, sprite) => {
    expect([sprite.width, sprite.height]).toEqual([8, 8])
    expect(sprite.rows).toHaveLength(8)
    for (const row of sprite.rows) {
      expect(row).toHaveLength(8)
      for (const key of row) if (key !== '.') expect(sprite.palette).toHaveProperty(key)
    }
  })

  it.each(Object.entries(BODY_SPRITES))('%s uses only Endesga 64 colors', (_name, sprite) => {
    expect(fromFile).toHaveLength(64)
    for (const color of Object.values(sprite.palette)) expect(fromFile).toContain(color)
  })
})

// The demo's two bodies as palette-indexed pixel maps, in base-2d's format (`PixelSprite`: each character is a
// key into the sprite's palette, `.` is transparent) and its Emberwick look: colored outlines, no black, a
// highlight on the top left where the moon is. Both are 8 × 8, the size of the bodies at 16 pixels a metre
// (a crate is half a metre; a stone, 0.44 m across, fills the box with its outline). Endesga 64 only, checked by
// art.test.ts. Provenance: PROVENANCE.md.
import type { PixelSprite } from '@af-examples/base-2d'

function sprite(palette: Readonly<Record<string, string>>, rows: readonly string[]): PixelSprite {
  return { width: rows[0]?.length ?? 0, height: rows.length, palette, rows }
}

/** A wooden crate with a band of moss on its lid and one diagonal brace. */
export const CRATE: PixelSprite = sprite(
  {
    O: '#391f21', // outline (Endesga 17)
    M: '#99e65f', // moss, lit (34)
    m: '#33984b', // moss (36)
    l: '#bf6f4a', // wood, lit (20)
    w: '#8a4836', // wood (19)
    s: '#5d2c28', // wood, shade (18)
  },
  ['.OOOOOO.', 'OMmMMmMO', 'OlmwwmsO', 'OwlwwwsO', 'OwwlwwsO', 'OwwwlwsO', 'OssssssO', '.OOOOOO.'],
)

/** A stone of lantern glass: cyan, lit from the top left, darker toward the bottom right. */
export const STONE: PixelSprite = sprite(
  {
    O: '#03193f', // outline (52)
    L: '#94fdff', // highlight (45)
    c: '#00cdf9', // glass (43)
    s: '#0098dc', // glass, shade (42)
  },
  ['..OOOO..', '.OLLccO.', 'OLLcccsO', 'OLccccsO', 'OccccssO', 'OcccsssO', '.OcsssO.', '..OOOO..'],
)

export const BODY_SPRITES: Readonly<Record<string, PixelSprite>> = { CRATE, STONE }

