// Makes the demo's sim: base-2d's sim with the physics extension and the demo's plugin, and the room's bodies.
import {
  base2dPlugin,
  createBaseSim,
  Player,
  parseRoom,
  ROOM,
  type RoomSource,
  tuning,
} from '@af-examples/base-2d'
import { BodyKind, body2d, collider2d, physics2d, transform2d } from '@mcthaydt/automata-physics/2d'
import type { PluginDef, Sim } from '@mcthaydt/automata-sim'
import { bodiesPlugin, crate, Follower, GRAVITY, PX_PER_M, stone, wickCentre } from './sim/bodies.plugin.ts'
import { roomColliders } from './sim/room-colliders.ts'

/**
 * Adds the bodies to a fresh base sim: the room's tiles as fixed bodies, the box that follows Wick, and the
 * starting crates and stones. Pass it to `playRoom` as `createSim`. This is setup, run once before the first
 * step, so it lives outside the sim folder; everything that runs each step is in sim/bodies.plugin.ts.
 */
export async function createBodiesSim(source: RoomSource): Promise<Sim> {
  const room = parseRoom(source)
  const heightPx = room.height * room.tileSize
  const sim = await createBaseSim({ room: source, plugins: demoPlugins(room) })
  for (const wall of roomColliders(room))
    sim.spawn([transform2d({ x: wall.x, y: wall.y }), collider2d.cuboid(wall.hx, wall.hy)])
  const [wick] = sim.query(Player)
  if (wick !== undefined)
    sim.spawn([
      transform2d(wickCentre(wick.get(Player), heightPx)),
      body2d(BodyKind.kinematicPosition),
      collider2d.cuboid(tuning.HITBOX_W / 2 / PX_PER_M, tuning.HITBOX_H / 2 / PX_PER_M),
      Follower,
    ])
  // A stack of crates on the floor right of the start, and stones on the first ledges.
  for (let i = 0; i < 4; i++) sim.spawn(crate(6.5, 0.8 + i * 0.5))
  for (const x of [2.2, 3, 3.8]) sim.spawn(stone(x, 6))
  return sim
}

/** The plugins the demo adds to base-2d's. */
function demoPlugins(room: ReturnType<typeof parseRoom>): PluginDef[] {
  return [physics2d({ gravity: { x: 0, y: GRAVITY } }), bodiesPlugin(room)]
}

/**
 * What a replay of the demo's sim needs to rebuild it: every plugin in createBaseSim's order and the same
 * content, so the schema and content hashes match the recording, and `create` to record one.
 */
export function bodiesSimSetup(source: RoomSource = ROOM) {
  const room = parseRoom(source)
  return {
    plugins: [base2dPlugin, ...demoPlugins(room)],
    content: { room },
    create: () => createBodiesSim(source),
  }
}

import { bootPage, CONNECT_FAILED, DEVICE_FAILED, ROOM } from '@af-examples/base-2d'
import { HostHandshakeFailed } from '@mcthaydt/automata-host'
import { Effect } from 'effect'
import { describe, expect, it, vi } from 'vitest'
import { createBodiesSim } from './bodies-sim.ts'
import { hostReady, playBodies } from './boot.ts'

// Rapier, the physics extension's lazily loaded wasm, failing to load: the demo's first sim cannot be made.
vi.mock('../../../packages/physics/src/rapier-2d.ts', () => ({
  createRapier2D: () => Promise.reject(new Error('wasm compile refused')),
}))

/** Runs a boot through base-2d's bootPage, with stand-ins for the page's elements. */
async function boot(start: Effect.Effect<void, unknown>) {
  const root = { textContent: '' as string | null }
  const html = { dataset: {} as Record<string, string | undefined> }
  const logged: unknown[] = []
  await bootPage({ root, html, start, log: (_message, error) => logged.push(error) })
  return { text: root.textContent, state: html.dataset.state, logged }
}

describe('the demo’s boot failures', () => {
  it('says this device can’t run the game when Rapier will not load', async () => {
    const result = await boot(playBodies(() => createBodiesSim(ROOM)).pipe(Effect.asVoid))
    expect(result.state).toBe('failed')
    expect(result.text).toBe(DEVICE_FAILED)
    // The log keeps the loader's own error, not just the tag.
    expect(String(result.logged[0])).toContain('wasm compile refused')
  })

  it('blames the connection only when the host handshake fails', async () => {
    const failed = Effect.fail(new HostHandshakeFailed({ reason: 'no-welcome' }))
    const result = await boot(hostReady(failed))
    expect(result.state).toBe('failed')
    expect(result.text).toBe(CONNECT_FAILED)
  })

  it('shows nothing extra when everything starts', async () => {
    const result = await boot(hostReady(Effect.void).pipe(Effect.zipRight(playBodies(async () => 'started'))))
    expect(result.state).toBe('ready')
    expect(result.text).toBe('')
  })
})

// How the demo's boot can fail, in base-2d's terms, so base-2d's bootPage shows the right message
// ("Couldn't connect to Ruken." or "This device can't run the game.") and sets data-state="failed".
import { BaseBootFailed, SimFailed } from '@af-examples/base-2d'
import { Effect } from 'effect'

/** The host handshake or ready: the only failure that is the connection's fault. */
export function hostReady<A, E, R>(connect: Effect.Effect<A, E, R>): Effect.Effect<A, BaseBootFailed, R> {
  return Effect.mapError(connect, (cause) => new BaseBootFailed({ step: 'ready', cause }))
}

/**
 * Starting the room: the renderer and the first sim. A rejection here (Rapier's wasm refused, no canvas context)
 * means this device can't run the game. A typed failure, not Effect.promise's defect, so bootPage can tell.
 */
export function playBodies<A>(start: () => Promise<A>): Effect.Effect<A, SimFailed> {
  return Effect.tryPromise({ try: start, catch: (cause) => new SimFailed({ cause }) })
}

// Vite bundles CSS imports (the font, the base's styles, the panel) into the build; TypeScript only needs to
// know they exist.
declare module '*.css' {}

import { expectGolden, replayGolden } from '@mcthaydt/automata-testing/sim'
import { recordGoldenEvidence } from '@mcthaydt/evidence/golden'
import { expect, it } from 'vitest'
import { bodiesSimSetup } from './bodies-sim.ts'
import { GOLDEN_HASH, goldenDrive, runGolden } from './golden.ts'

it('the golden run ends on the recorded hash', async ({ task }) => {
  const result = await runGolden()
  expect(result.rejected).toBe(0)
  // The bodies did collide: a run where nothing touched would pin nothing about the physics.
  expect(result.collisions).toBeGreaterThan(10)
  expect(result.hash).toBe(GOLDEN_HASH)
  // The hash this engine computed, for the evidence file (DX.9).
  const { seed, ticks, hash } = result
  recordGoldenEvidence(task, { scenario: 'physics-bodies-2d/golden-run', seed, ticks, hash })
})

it('replays to the same hash twice in one engine', async () => {
  const first = await runGolden()
  const second = await runGolden()
  expect(second.hash).toBe(first.hash)
})

// The same run as a .replay (M2.3), with a reference snapshot every 30 ticks: when the run changes, the report
// names the first tick that differs and every field that differs there. Every 10 ticks would pack to 497 KB, so
// close to the 512 KiB golden cap that any growth would break it; every 30 is 175 KB. Recorded in Node with
// AUTOMATA_UPDATE_GOLDENS=1; golden.parity.test.ts checks it in Chromium, WebKit and Firefox.
it('bodies.replay: the golden run replays tick for tick', async () => {
  const report = await replayGolden({
    file: './__goldens__/bodies.replay',
    ...bodiesSimSetup(),
    record: { create: () => bodiesSimSetup().create(), drive: goldenDrive, snapshotEvery: 30 },
  })
  expectGolden(report)
  expect(report.kind === 'pass' || report.kind === 'written').toBe(true)
})

// A scripted run of the demo's sim: Wick walks into the crates, jumps, and walks back while bodies drop on fixed
// ticks (some under the low platform, so the drop's climb above it is pinned too). The
// golden tests replay it and compare the final state hash, in Node (golden.test.ts) and in Chromium, WebKit and
// Firefox (golden.parity.test.ts): the pile must come out bit for bit the same on every engine (AGENTS.md,
// determinism). A change to the bodies, the physics extension or the base's sim changes the hash on purpose:
// investigate it, never rebaseline it per engine.
import { moveCommand, ROOM } from '@af-examples/base-2d'
import type { Command, Sim, StepResult } from '@mcthaydt/automata-sim'
import type { Recorder } from '@mcthaydt/automata-sim/replay'
import { createBodiesSim } from './bodies-sim.ts'
import { Drop } from './sim/bodies.plugin.ts'

/** Ticks the golden run lasts (ten seconds): long enough for every drop to land and the pile to settle. */
export const GOLDEN_TICKS = 600
/** The ticks a body drops on: a crate on even ticks, a stone on odd ones. */
export const GOLDEN_DROPS: readonly number[] = [10, 25, 26, 60, 61, 62, 63, 120, 121, 200, 240, 241, 400, 401]
/** The sim's state hash after the golden run, re-recorded in Node on 2026-10-11 (M2.1b: Prop tags, drop heights, the jump). */
export const GOLDEN_HASH = 'ad621eea6325a8db'

/** Wick walks right for 90 ticks, waits, walks back left for 90, then waits out the rest. */
function wickX(tick: number): -1 | 0 | 1 {
  if (tick < 90) return 1
  if (tick >= 150 && tick < 240) return -1
  return 0
}

/** Wick jumps (holding the button for a full jump) while walking into the crates. */
const wickJumps = (tick: number) => tick >= 70 && tick < 82

/** Steps `sim` through the golden run with `step` (sim.step, or a recorder's step); returns every result. */
function drive(sim: Sim, step: (commands: readonly Command[]) => StepResult): StepResult[] {
  const results: StepResult[] = []
  for (let i = 0; i < GOLDEN_TICKS; i++) {
    const commands: Command[] = [moveCommand(sim, { x: wickX(sim.tick), jump: wickJumps(sim.tick) })]
    if (GOLDEN_DROPS.includes(sim.tick))
      commands.push({ tick: sim.tick, source: 0, seq: 0x80000000 + sim.tick, type: Drop.id, payload: {} })
    results.push(step(commands))
  }
  return results
}

/** Records the golden run (golden.test.ts's bodies.replay). */
export function goldenDrive(recorder: Recorder, sim: Sim): void {
  drive(sim, (commands) => recorder.step(commands))
}

/** Replays the golden run on a fresh sim and reports what the golden tests compare. */
export async function runGolden(): Promise<{
  hash: string
  rejected: number
  collisions: number
  seed: number
  ticks: number
}> {
  const sim = await createBodiesSim(ROOM)
  const startTick = sim.tick
  const results = drive(sim, (commands) => sim.step(commands))
  let rejected = 0
  let collisions = 0
  for (const result of results) {
    rejected += result.rejected.length
    for (const event of result.events) if (event.type === 'physics2d.collision-started') collisions++
  }
  const hash = sim.hash()
  const ticks = sim.tick - startTick
  sim.dispose()
  return { hash, rejected, collisions, seed: sim.seed, ticks }
}

import { moveCommand, ROOM } from '@af-examples/base-2d'
import { Transform2D } from '@mcthaydt/automata-physics/2d'
import type { Command, Sim, StepResult } from '@mcthaydt/automata-sim'
import { type Sprite, Texture } from 'pixi.js'
import { afterEach, describe, expect, it } from 'vitest'
import { createBodiesSim } from './bodies-sim.ts'
import { bodiesLayer, type Drawn } from './layer.ts'
import { Drop, MAX_LOOSE, Prop, PropKind } from './sim/bodies.plugin.ts'

// The layer draws from the sim's RenderDelta alone, the way render-pixi will: it never reads the sim.
const sims: Sim[] = []
afterEach(() => {
  for (const sim of sims.splice(0)) sim.dispose()
})

const textures = { crate: Texture.WHITE, stone: Texture.EMPTY }
const step = (sim: Sim, x: -1 | 0 | 1 = 0): StepResult => sim.step([moveCommand(sim, { x, jump: false })])
const sprites = (layer: ReturnType<typeof bodiesLayer>) => layer.view.children as Sprite[]

describe('bodiesLayer', () => {
  it('makes one sprite per loose body, with the crate or stone texture, in room pixels', async () => {
    const sim = await createBodiesSim(ROOM)
    sims.push(sim)
    const layer = bodiesLayer(ROOM.rows.length * ROOM.tileSize, textures)
    layer.apply?.(step(sim))
    expect(sprites(layer)).toHaveLength(7)
    expect(sprites(layer).filter((s) => s.texture === Texture.WHITE)).toHaveLength(4)
    expect(sprites(layer).filter((s) => s.texture === Texture.EMPTY)).toHaveLength(3)
    // Positions are whole pixels (y flipped: 192 px minus metres × 16), whatever Rapier's floats.
    const crate = sim
      .query(Prop, Transform2D)
      .find((body) => body.get(Prop).kind === PropKind.crate) as NonNullable<ReturnType<Sim['entity']>>
    const at = crate.get(Transform2D)
    const drawn = sprites(layer).map((s) => [s.x, s.y])
    expect(drawn).toContainEqual([Math.round(at.x * 16), Math.round(192 - at.y * 16)])
    for (const [x, y] of drawn) {
      expect(Number.isInteger(x)).toBe(true)
      expect(Number.isInteger(y)).toBe(true)
    }
  })

  it('moves sprites with their bodies, and forgets them on a reset', async () => {
    const sim = await createBodiesSim(ROOM)
    sims.push(sim)
    const layer = bodiesLayer(ROOM.rows.length * ROOM.tileSize, textures)
    layer.apply?.(step(sim))
    const before = sprites(layer).map((s) => s.y)
    for (let i = 0; i < 20; i++) layer.apply?.(step(sim))
    const after = sprites(layer).map((s) => s.y)
    expect(after).toHaveLength(7)
    // Everything starts in the air, so after a third of a second of falling some sprite is lower on screen.
    expect(after.some((y, i) => y > (before[i] as number))).toBe(true)
    layer.reset?.()
    expect(sprites(layer)).toHaveLength(0)
  })

  it('starts over on a resync delta, keeping only the bodies it lists', async () => {
    const sim = await createBodiesSim(ROOM)
    sims.push(sim)
    const layer = bodiesLayer(ROOM.rows.length * ROOM.tileSize, textures)
    const first = step(sim)
    layer.apply?.(first)
    expect(sprites(layer)).toHaveLength(7)
    const [one] = first.render.added.filter((row) => row.components[Prop.id] !== undefined)
    const resync: StepResult = {
      ...first,
      render: { resync: true, added: one ? [one] : [], changed: [], removed: [] },
    }
    layer.apply?.(resync)
    expect(sprites(layer)).toHaveLength(1)
  })

  it('reports how many bodies it drew and where the rightmost crate is', async () => {
    const sim = await createBodiesSim(ROOM)
    sims.push(sim)
    const drawn: Drawn[] = []
    const layer = bodiesLayer(ROOM.rows.length * ROOM.tileSize, textures, (d) => drawn.push(d))
    layer.apply?.(step(sim))
    // The crate stack starts at x = 6.5 m, 104 px.
    expect(drawn.at(-1)).toEqual({ count: 7, crateX: 104 })
  })

  it('drops the sprite of a body the sim removed', async () => {
    const sim = await createBodiesSim(ROOM)
    sims.push(sim)
    const layer = bodiesLayer(ROOM.rows.length * ROOM.tileSize, textures)
    // One drop a tick until the sim holds MAX_LOOSE bodies, then one more: the sim removes the oldest.
    for (let i = 0; i <= MAX_LOOSE - 7; i++) {
      const drop: Command = {
        tick: sim.tick,
        source: 0,
        seq: 0x80000000 + sim.tick,
        type: Drop.id,
        payload: {},
      }
      layer.apply?.(sim.step([moveCommand(sim, { x: 0, jump: false }), drop]))
    }
    expect(sim.query(Prop)).toHaveLength(MAX_LOOSE)
    expect(sprites(layer)).toHaveLength(MAX_LOOSE)
  })
})

// The bodies, as a layer on base-2d's renderer: one 8 × 8 sprite per crate or stone, drawn from the sim's
// RenderDelta alone, the way render-pixi (M1.7) drives views. The layer never reads the sim: each step's delta
// says which bodies appeared, moved or went (`added`, `changed`, `removed`), and a `resync` delta lists every
// body afresh. Walls carry no `Prop`, so they draw nothing here (the room's tiles already show them). The
// layer sits under the room's light map, so Wick's lantern and the ember light the bodies like the room.

import type { RendererLayer } from '@af-examples/base-2d/render'
import { Transform2D } from '@mcthaydt/automata-physics/2d'
import type { RenderRow } from '@mcthaydt/automata-sim'
import { Container, Sprite, type Texture } from 'pixi.js'
import { Prop, PropKind, PX_PER_M } from './sim/bodies.plugin.ts'

export interface BodyTextures {
  readonly crate: Texture
  readonly stone: Texture
}

/** What the layer drew after a step, for the page's data attributes (the browser journeys read them). */
export interface Drawn {
  /** Sprites on screen. */
  readonly count: number
  /** The rightmost crate's x in room pixels, or -1 with no crate; a shove moves it. */
  readonly crateX: number
}

/** `roomHeightPx` flips physics' y (up) to the room's (down). `onDrawn` hears what is drawn after each step. */
export function bodiesLayer(
  roomHeightPx: number,
  textures: BodyTextures,
  onDrawn: (drawn: Drawn) => void = () => {},
): RendererLayer {
  const view = new Container()
  const sprites = new Map<number, Sprite>()

  const forget = (sid: number) => {
    sprites.get(sid)?.destroy()
    sprites.delete(sid)
  }
  const clear = () => {
    for (const sid of [...sprites.keys()]) forget(sid)
  }

  // A row carries the entity's whole render state, so a body without Prop or Transform2D is not ours to draw.
  const place = (row: RenderRow) => {
    const prop = row.components[Prop.id]
    const at = row.components[Transform2D.id]
    if (prop === undefined || at === undefined) return forget(row.sid)
    let sprite = sprites.get(row.sid)
    if (sprite === undefined) {
      sprite = new Sprite(prop.kind === PropKind.crate ? textures.crate : textures.stone)
      sprite.anchor.set(0.5)
      sprites.set(row.sid, sprite)
      view.addChild(sprite)
    }
    // Whole pixels, so the pixel art never lands between screen pixels. Rapier's angle is counter-clockwise
    // with y up; on screen y points down, so the sprite turns the other way.
    sprite.position.set(
      Math.round((at.x as number) * PX_PER_M),
      Math.round(roomHeightPx - (at.y as number) * PX_PER_M),
    )
    sprite.rotation = -(at.rotation as number)
  }

  return {
    view,
    apply(result) {
      const delta = result.render
      if (delta.resync) clear()
      for (const row of delta.added) place(row)
      for (const row of delta.changed) place(row)
      for (const sid of delta.removed) forget(sid)
      let crateX = -1
      for (const sprite of sprites.values())
        if (sprite.texture === textures.crate) crateX = Math.max(crateX, sprite.x)
      onDrawn({ count: sprites.size, crateX })
    },
    // A new round starts a fresh sim, whose first delta is a resync; drop the old round's sprites now.
    reset: clear,
  }
}

// examples/physics/bodies-2d: Rapier rigid bodies in the 2D room, through the physics extension.
//
// Shows: @mcthaydt/automata-physics/2d inside base-2d's sim. The room's tiles are fixed bodies, an invisible
// kinematic box follows Wick, and crates and stones are dynamic bodies: Wick shoves them, they tumble down the
// ledges and pile up. Drop more and watch the collision events count up. Physics runs inside the sim
// (sim/bodies.plugin.ts), so the pile is the same on every engine (golden.parity.test.ts); this page only
// sends the drops and draws the bodies.
// Files: boot.ts types the boot failures for base-2d's bootPage; bodies-sim.ts makes the sim and places the bodies (walls from sim/room-colliders.ts); sim/ is what runs
// each step; layer.ts draws the bodies from the sim's RenderDelta with the 8 × 8 sprites in art/.
// Controls: arrows or A/D to move, Space, Z, W or Up to jump, B, X or C to drop a body above Wick; on-screen
// buttons on touch (▣ drops).
// Base: base-2d (`@af-examples/base-2d`: the room, Wick, input and the loop through `playRoom`).
// Packages: @mcthaydt/automata-physics (Rapier, deterministic build), @mcthaydt/automata-host, pixi.js, effect,
// and the base's own.
import '@af-examples/base-2d/no-eval'
import '@fontsource/pixelify-sans/latin-400.css'
import '@fontsource/pixelify-sans/latin-700.css'
import '@af-examples/base-2d/style.css'
import './bodies-panel.css'
import { bootPage, ROOM } from '@af-examples/base-2d'
import { playRoom } from '@af-examples/base-2d/play'
import { textureFromPixels } from '@af-examples/base-2d/render'
import { makeHosting } from '@mcthaydt/automata-host'
import type { Command, Sim } from '@mcthaydt/automata-sim'
import { Effect, Scope } from 'effect'
import { CRATE, STONE } from './art/sprites.ts'
import { createBodiesSim } from './bodies-sim.ts'
import { hostReady, playBodies } from './boot.ts'
import { bodiesLayer } from './layer.ts'
import { Drop } from './sim/bodies.plugin.ts'

/** Must equal `[game] id` in ship.config.ts; the host checks it. */
const GAME_ID = 'demo-physics-bodies-2d'

const found = document.querySelector<HTMLElement>('#game')
if (found === null) throw new Error('index.html has no #game element')
const root: HTMLElement = found

// Drops wait here until the next sim step sends them as commands (input never changes the sim directly).
let dropsWanted = 0
const DROP_KEYS = new Set(['KeyB', 'KeyX', 'KeyC'])
window.addEventListener('keydown', (event) => {
  if (DROP_KEYS.has(event.code) && !event.repeat) dropsWanted++
})

/**
 * At most one drop per step; any more wait for the next. The base's `move` takes `seq = tick` for player 0, so
 * a drop takes a number from the top half of the u32 range, where `move` will not reach for over a year of play.
 */
function dropCommands(sim: Sim): Command[] {
  if (dropsWanted === 0) return []
  dropsWanted--
  return [{ tick: sim.tick, source: 0, seq: 0x80000000 + sim.tick, type: Drop.id, payload: {} }]
}

const program = Effect.gen(function* () {
  yield* hostReady(
    Effect.gen(function* () {
      const hosting = yield* makeHosting({ gameId: GAME_ID, wants: [], pauseBehavior: 'pause' })
      yield* hosting.ready
    }),
  )
  // Nothing was drawn before this line: the page stays empty until the host says ready.
  let bumps = 0
  const counter = document.createElement('aside')
  counter.className = 'bodies-panel'
  const showBumps = () => {
    counter.textContent = `Collisions: ${bumps}`
    root.dataset.bumps = String(bumps)
  }
  const bodies = bodiesLayer(
    ROOM.rows.length * ROOM.tileSize,
    { crate: textureFromPixels(CRATE), stone: textureFromPixels(STONE) },
    (drawn) => {
      root.dataset.bodies = String(drawn.count)
      root.dataset.crateX = String(drawn.crateX)
    },
  )
  const play = yield* playBodies(() =>
    playRoom(root, {
      createSim: createBodiesSim,
      commands: dropCommands,
      onStep: (result) => {
        const started = result.events.filter((event) => event.type === 'physics2d.collision-started').length
        if (started > 0) {
          bumps += started
          showBumps()
        }
      },
      layers: [bodies],
    }),
  )
  // A touch button for drops, beside the base's move and jump buttons.
  const dropButton = document.createElement('button')
  dropButton.type = 'button'
  dropButton.className = 'drop'
  dropButton.textContent = '▣'
  dropButton.setAttribute('aria-label', 'Drop a body')
  dropButton.addEventListener('pointerdown', (event) => {
    event.preventDefault()
    dropsWanted++
  })
  root.querySelector('.touch .jump')?.before(dropButton)
  root.append(counter)
  showBumps()
  play.start()
})

// The host connection lives as long as the page, so its scope is never closed. bootPage sets data-state to
// ready, or shows base-2d's failure message ("This device can't run the game." when Rapier won't load).
const pageScope = Effect.runSync(Scope.make())
void bootPage({
  root,
  html: document.documentElement,
  start: program.pipe(Scope.extend(pageScope)),
  log: (message, error) => console.error(message, error),
})

// What ship writes into this demo's ruken.toml (ship spec §3.2): the base's settings under the demo's own id.
import { defineShipConfig } from '@mcthaydt/automata-ship'
import packageJson from './package.json' with { type: 'json' }

export default defineShipConfig({
  game: {
    id: 'demo-physics-bodies-2d',
    title: 'AF demo: physics bodies 2D',
    version: packageJson.version,
    entry: 'index.html',
    sdk: '^0.0.0',
  },
  runtime: { renderer: 'webgl2', orientation: 'any', inputs: ['touch', 'keyboard'], pause_behavior: 'pause' },
  network: { connect: [] },
  content: { languages: ['en'], rating: 'everyone', descriptors: [] },
})

// The demo's sim half: Rapier bodies in base-2d's room, through @mcthaydt/automata-physics/2d.
//
// Three kinds of body:
// - fixed: the room's solid tiles, one cuboid per run of `#` in a row (fewer bodies than one per tile);
// - kinematic: an invisible box that follows Wick, so Wick shoves bodies around (Wick still moves by the
//   base's own tile collision; physics never moves Wick);
// - dynamic: crates and stones, a few to start and one more per `drop` command.
//
// Units: physics works in metres with y up; the room is in pixels with y down. 16 pixels are a metre, so a tile
// is half a metre and the room 20 × 12 m. Everything here runs inside the sim: no I/O, no clock, no
// randomness, so the same drops give the same pile in every browser (bodies.parity.test.ts). `pnpm boundaries`
// checks this folder; it imports only the sim, the physics extension and the base's sim
// (`@af-examples/base-2d/sim`), never the base's package root, which reaches the host bridge.
import { isSolid, Player, type RoomGrid, tuning } from '@af-examples/base-2d/sim'
import {
  BodyKind,
  body2d,
  collider2d,
  RigidBody2D,
  Transform2D,
  transform2d,
} from '@mcthaydt/automata-physics/2d'
import {
  defineCommand,
  defineComponent,
  definePlugin,
  defineSystem,
  type PluginDef,
  type SpawnPart,
} from '@mcthaydt/automata-sim'
import { z } from 'zod'

export const PX_PER_M = 16
/** Stronger than Earth's 9.81, so 8-pixel crates fall as briskly as Wick does. */
export const GRAVITY = -40
/** Past this many loose bodies, the oldest is removed to make room for a new drop. */
export const MAX_LOOSE = 40

/** Marks the kinematic box that follows Wick; `player` is the player slot it follows (always 0 here). */
export const Follower = defineComponent('bodies.follower', { player: 'u32' })

/** What a loose body looks like: the renderer draws a crate or a stone from this. */
export const PropKind = { crate: 0, stone: 1 } as const
/**
 * Rendered, unlike RigidBody2D and Collider2D: it is how the drawing layer, which sees only the sim's
 * RenderDelta, tells a crate from a stone (and a loose body from a wall).
 */
export const Prop = defineComponent('bodies.prop', { kind: 'u32' })

/** Drop a body just above Wick: a crate on even ticks, a stone on odd ones. */
export const Drop = defineCommand('bodies.drop', z.object({}))

/** Room pixels to metres, for a point (y flips). */
export const metresX = (px: number) => px / PX_PER_M
export const metresY = (py: number, roomHeightPx: number) => (roomHeightPx - py) / PX_PER_M

export const crate = (x: number, y: number): SpawnPart[] => [
  transform2d({ x, y }),
  body2d(BodyKind.dynamic, { angularDamping: 0.5 }),
  collider2d.cuboid(0.25, 0.25, { friction: 0.8 }),
  [Prop, { kind: PropKind.crate }],
]
export const stone = (x: number, y: number): SpawnPart[] => [
  transform2d({ x, y }),
  body2d(BodyKind.dynamic, { angularDamping: 0.2 }),
  collider2d.ball(0.22, { friction: 0.6, restitution: 0.45 }),
  [Prop, { kind: PropKind.stone }],
]

/** Where Wick's hitbox centre is, in metres. */
export function wickCentre(player: { x: number; y: number }, roomHeightPx: number) {
  const px = player.x / tuning.SUB + tuning.HITBOX_W / 2
  const py = player.y / tuning.SUB + tuning.HITBOX_H / 2
  return { x: metresX(px), y: metresY(py, roomHeightPx) }
}

/** How high above Wick's centre a drop starts. */
export const DROP_ABOVE = 1.25

/**
 * Where a drop starts: `DROP_ABOVE` over Wick, or, if that spot is inside a platform (Wick walks under them),
 * a tile higher at a time until it is clear, so Rapier never has to push a body out of a wall.
 */
export function dropHeight(room: RoomGrid, x: number, wickY: number): number {
  const heightPx = room.height * room.tileSize
  const half = 0.25 // a crate's half size, and a little more than a stone's radius
  const tileM = room.tileSize / PX_PER_M
  let y = wickY + DROP_ABOVE
  while (y < heightPx / PX_PER_M && boxTouchesSolid(room, x, y, half)) y += tileM
  return y
}

function boxTouchesSolid(room: RoomGrid, x: number, y: number, half: number): boolean {
  const heightPx = room.height * room.tileSize
  // The box's edges in room pixels (y down). The right and bottom edges are exclusive, so a box that only
  // touches a tile's edge does not count as inside it.
  const left = Math.floor(((x - half) * PX_PER_M) / room.tileSize)
  const right = Math.ceil(((x + half) * PX_PER_M) / room.tileSize) - 1
  const top = Math.floor((heightPx - (y + half) * PX_PER_M) / room.tileSize)
  const bottom = Math.ceil((heightPx - (y - half) * PX_PER_M) / room.tileSize) - 1
  for (let ty = top; ty <= bottom; ty++)
    for (let tx = left; tx <= right; tx++) if (isSolid(room, tx, ty)) return true
  return false
}

export function bodiesPlugin(room: RoomGrid): PluginDef {
  const roomHeightPx = room.height * room.tileSize
  return definePlugin({
    name: 'bodies-2d-demo',
    commands: [Drop],
    systems: [
      defineSystem({
        name: 'bodies.drop',
        phase: 'input',
        run(ctx) {
          const [wick] = ctx.query(Player)
          if (wick === undefined) return
          for (const _ of ctx.commands.of(Drop)) {
            const loose = ctx
              .query(RigidBody2D)
              .filter((body) => body.get(RigidBody2D).kind === BodyKind.dynamic)
            // Bodies come back in ascending id order, so the first is the oldest.
            const oldest = loose[0]
            if (loose.length >= MAX_LOOSE && oldest !== undefined) ctx.despawn(oldest.sid)
            const at = wickCentre(wick.get(Player), roomHeightPx)
            // A small sideways nudge that changes with the tick, so drops on one spot topple into a pile
            // instead of balancing in a perfect column.
            const x = at.x + ((ctx.tick % 5) - 2) * 0.05
            const y = dropHeight(room, x, at.y)
            const parts = ctx.tick % 2 === 0 ? crate(x, y) : stone(x, y)
            ctx.spawn(...parts)
          }
        },
      }),
      defineSystem({
        // After the base has moved Wick this tick; the physics step picks the new position up next tick.
        name: 'bodies.follow-wick',
        phase: 'postPhysics',
        run(ctx) {
          const [wick] = ctx.query(Player)
          const [follower] = ctx.query(Transform2D, Follower)
          if (wick === undefined || follower === undefined) return
          follower.set(Transform2D, wickCentre(wick.get(Player), roomHeightPx))
        },
      }),
    ],
    components: [Follower, Prop],
  })
}

import { moveCommand, ROOM } from '@af-examples/base-2d'
import { BodyKind, RigidBody2D, Transform2D } from '@mcthaydt/automata-physics/2d'
import type { Command, Sim } from '@mcthaydt/automata-sim'
import { afterEach, describe, expect, it } from 'vitest'
import { createBodiesSim } from '../bodies-sim.ts'
import { DROP_ABOVE, Drop, Follower, MAX_LOOSE, Prop, PropKind } from './bodies.plugin.ts'

const sims: Sim[] = []
afterEach(() => {
  for (const sim of sims.splice(0)) sim.dispose()
})
const make = async () => {
  const sim = await createBodiesSim(ROOM)
  sims.push(sim)
  return sim
}

const drop = (sim: Sim): Command => ({
  tick: sim.tick,
  source: 0,
  seq: 0x80000000 + sim.tick,
  type: Drop.id,
  payload: {},
})
const loose = (sim: Sim) =>
  sim.query(RigidBody2D).filter((body) => body.get(RigidBody2D).kind === BodyKind.dynamic)

/** Runs `ticks` steps with Wick holding `x` and the given drops on the given ticks. */
function run(sim: Sim, ticks: number, x: -1 | 0 | 1 = 0, dropOn: readonly number[] = []) {
  for (let i = 0; i < ticks; i++) {
    const commands = [moveCommand(sim, { x, jump: false })]
    if (dropOn.includes(sim.tick)) commands.push(drop(sim))
    const result = sim.step(commands)
    expect(result.rejected).toEqual([])
  }
}

describe('bodies in the room', () => {
  it('starts with four crates and three stones, which fall and come to rest', async () => {
    const sim = await make()
    expect(loose(sim)).toHaveLength(7)
    const heights = () => loose(sim).map((body) => body.get(Transform2D).y)
    const start = heights()
    run(sim, 180)
    const settled = heights()
    run(sim, 30)
    expect(settled.some((y, i) => y < (start[i] as number) - 0.1)).toBe(true)
    // Resting: nothing moves more than a hair in another half second.
    for (const [i, y] of heights().entries()) expect(Math.abs(y - (settled[i] as number))).toBeLessThan(0.02)
    // Nothing fell through the floor (its top is half a metre up).
    for (const y of heights()) expect(y).toBeGreaterThan(0.5)
  })

  it('drops a body above Wick, and the box that follows Wick moves with Wick', async () => {
    const sim = await make()
    const follower = () =>
      (sim.query(Transform2D, Follower)[0] as NonNullable<ReturnType<Sim['entity']>>).get(Transform2D)
    const before = follower().x
    run(sim, 40, 1, [5])
    expect(loose(sim)).toHaveLength(8)
    expect(follower().x).toBeGreaterThan(before + 0.5)
  })

  it(`keeps at most ${MAX_LOOSE} loose bodies, removing the oldest`, async () => {
    const sim = await make()
    const first = loose(sim)[0]?.sid
    run(
      sim,
      MAX_LOOSE,
      0,
      Array.from({ length: MAX_LOOSE }, (_, i) => i),
    )
    expect(loose(sim)).toHaveLength(MAX_LOOSE)
    expect(loose(sim).map((body) => body.sid)).not.toContain(first)
  })

  it('lets Wick shove the crate stack to the right', async () => {
    const sim = await make()
    const crates = () => loose(sim).filter((body) => body.get(Prop).kind === PropKind.crate)
    run(sim, 60) // let the stack settle first
    const before = Math.max(...crates().map((body) => body.get(Transform2D).x))
    run(sim, 90, 1)
    const after = Math.max(...crates().map((body) => body.get(Transform2D).x))
    expect(after).toBeGreaterThan(before + 0.25)
  })

  it('tags every loose body with what it looks like, and sends that to the renderer', async () => {
    const sim = await make()
    const kinds = loose(sim).map((body) => body.get(Prop).kind)
    expect(kinds.filter((kind) => kind === PropKind.crate)).toHaveLength(4)
    expect(kinds.filter((kind) => kind === PropKind.stone)).toHaveLength(3)
    // The first step's delta is a resync listing every rendered entity; the loose bodies come with their
    // Prop and Transform2D (RigidBody2D and Collider2D are not rendered, so the layer cannot tell them apart).
    const result = sim.step([moveCommand(sim, { x: 0, jump: false })])
    const props = result.render.added.filter((row) => row.components[Prop.id] !== undefined)
    expect(props).toHaveLength(7)
    for (const row of props) expect(row.components[Transform2D.id]).toBeDefined()
  })

  /** Drops one body on the next tick and returns where it is after that step, with Wick's centre before it. */
  function dropOne(sim: Sim) {
    const wick = (sim.query(Transform2D, Follower)[0] as NonNullable<ReturnType<Sim['entity']>>).get(
      Transform2D,
    )
    const ids = new Set(loose(sim).map((body) => body.sid))
    run(sim, 1, 0, [sim.tick])
    const dropped = loose(sim).find((body) => !ids.has(body.sid))
    if (dropped === undefined) throw new Error('nothing dropped')
    return { wick, at: dropped.get(Transform2D) }
  }

  it(`drops the new body ${DROP_ABOVE} m above Wick where nothing is in the way`, async () => {
    const sim = await make()
    run(sim, 60, -1) // to the left wall, where no platform hangs over Wick
    run(sim, 2) // stop, and let the box that follows Wick catch up
    const { wick, at } = dropOne(sim)
    expect(wick.x).toBeLessThan(1)
    // One step of gravity has already pulled it down a hair.
    expect(at.y).toBeGreaterThan(wick.y + DROP_ABOVE - 0.05)
    expect(at.y).toBeLessThanOrEqual(wick.y + DROP_ABOVE)
  })

  it('drops it above the platform instead when Wick stands under one', async () => {
    const sim = await make()
    run(sim, 2)
    // At the start Wick is under the low platform (row 20, its top 2 m up): 1.25 m above him is inside it.
    const { wick, at } = dropOne(sim)
    expect(wick.y + DROP_ABOVE).toBeLessThan(2.25)
    expect(at.y).toBeGreaterThan(wick.y + DROP_ABOVE + 0.45)
    expect(at.y).toBeLessThanOrEqual(wick.y + DROP_ABOVE + 0.5)
  })

  it('gives the same pile for the same drops', async () => {
    const a = await make()
    const b = await make()
    run(a, 120, 1, [3, 20, 40])
    run(b, 120, 1, [3, 20, 40])
    expect(a.hash()).toBe(b.hash())
  })
})

