}

function target(): HTMLElement {
  return document.body.appendChild(document.createElement('div'))
}

async function readyOn(root: HTMLElement): Promise<void> {
  await vi.waitFor(() => expect(root.dataset.ready).toBe(''), { timeout: 5000 })
}

