/**
 * Emberwick's screens and how they connect, as the runtime reads them (it checks the hash at boot). The
 * runtime pauses the room itself when the host goes to the background or opens its menu (`openMenu`).
 */
export const EMBERWICK_FLOW: { readonly data: CompiledContentData; readonly hash: string } = {
  data: FLOW_DATA,
  hash: hex64(xxhash64(utf8(canonicalJson(FLOW_DATA)))),
}

// `@af-examples/base-2d/game`: the base's whole game as one `defineGame` result, for `startGame`. A separate
// entry from the package root because the game loads Pixi, the runtime and the screens; the root and ./sim
// stay light for Node code. bootPage and the boot failures (for the demos) are in the root.

export { emberwick, input } from './game.ts'

// Emberwick as one `defineGame` call (DX.3): the base's sim, the keys that drive it, its own screens over its
// own flow, and its scene drawn through render-pixi's stage hooks. `main.ts` passes it to `startGame`.
import { defineGame, keys } from '@mcthaydt/automata-game'
import type { Sim } from '@mcthaydt/automata-sim'
import { parseRoom, ROOM } from './content/room.ts'
import { EMBERWICK_FLOW } from './flow.ts'
import { sceneRenderer, type WickAt } from './render/scene-renderer.ts'
import { emberwickScreens } from './screens/emberwick-screens.ts'
import { base2dPlugin, Move } from './sim/index.ts'
import { placeWick } from './sim/place-wick.ts'

const room = parseRoom(ROOM)

/** By `KeyboardEvent.code`; nothing held is "stand still" (`idle`), sent every tick as the sim expects. */
export const input = keys(
  Move,
  {
    ArrowLeft: { x: -1 },
    KeyA: { x: -1 },
    ArrowRight: { x: 1 },
    KeyD: { x: 1 },
    Space: { jump: true },
    KeyZ: { jump: true },
    KeyW: { jump: true },
    ArrowUp: { jump: true },
  },
  { idle: { x: 0, jump: false } },
)

const sim = { plugins: [base2dPlugin], seed: 1, setup: (made: Sim) => placeWick(made, room) }

/** The page's record of where Wick is and how far the sim has run (the browser journeys read it). */
function showWick(at: WickAt): void {
  const root = document.getElementById('game')
  if (root === null) return
  root.dataset.playerX = String(at.x)
  root.dataset.playerY = String(at.y)
  root.dataset.tick = String(at.tick)
}

export const emberwick = defineGame({
  id: 'base-2d',
  title: 'Emberwick',
  size: { width: room.width * room.tileSize, height: room.height * room.tileSize },
  sim,
  input,
  // The flow for the runtime; the room is the sim's content (`sim.content.room`).
  content: { ...EMBERWICK_FLOW, sim: { room } },
  screens: emberwickScreens({ sim: { ...sim, content: { room } }, input }),
  // 'menu' lets the host's "Open game menu" reach the room (its `openMenu`).
  hosting: { wants: ['menu'] },
  renderer: sceneRenderer(room, showWick),
})

import { type Command, createSim } from '@mcthaydt/automata-sim'
import { emberwick } from './game.ts'
import { routeInputs } from './golden.ts'
import type { MoveInput } from './sim/index.ts'

/** The keys the golden route holds: one per direction, Z for jump. */
const keysFor = (input: MoveInput): string[] => [
  ...(input.x === -1 ? ['ArrowLeft'] : input.x === 1 ? ['ArrowRight'] : []),
  ...(input.jump ? ['KeyZ'] : []),
]

/** Just enough of a window for `keys()`: key events and no gamepads. */
function fakeWindow(): Window {
  const target = new EventTarget() as EventTarget & { navigator: { getGamepads: () => [] } }
  target.navigator = { getGamepads: () => [] }
  return target as unknown as Window
}

function press(target: Window, type: 'keydown' | 'keyup', code: string): void {
  const event = new Event(type, { cancelable: true })
  Object.defineProperty(event, 'code', { value: code })
  target.dispatchEvent(event)
}

/**
 * Replays the golden route the way `startGame` plays Emberwick: a sim made from the game's own sim spec (seed,
 * plugins, the room as content, Wick placed by `setup`), stepped each tick with the command its input map
 * builds from the keys held. Reports what the golden tests compare.
 */
export async function runGolden(): Promise<{
  hash: string
  goalTicks: number[]
  rejected: number
  inputs: MoveInput[]
  commands: Command[]
  seed: number
  ticks: number
}> {
  const { plugins, seed, content, setup } = emberwick.sim
  const sim = await createSim({ plugins: [...plugins], seed, content })
  setup?.(sim)
  const startTick = sim.tick
  const target = fakeWindow()
  const source = emberwick.input?.attach(target)
  if (source === undefined) throw new Error('emberwick has no input map')

  const inputs = routeInputs()
  const commands: Command[] = []
  const goalTicks: number[] = []
  let rejected = 0
  let held: string[] = []
  for (const input of inputs) {
    const wanted = keysFor(input)
    for (const code of held) if (!wanted.includes(code)) press(target, 'keyup', code)
    for (const code of wanted) if (!held.includes(code)) press(target, 'keydown', code)
    held = wanted
    const step = source.commands(sim.tick)
    commands.push(...step)
    const result = sim.step(step)
    rejected += result.rejected.length
    for (const event of result.events) if (event.type === 'goal.reached') goalTicks.push(result.tick)
  }
  source.dispose()
  const hash = sim.hash()
  const ticks = sim.tick - startTick
  sim.dispose()
  return { hash, goalTicks, rejected, inputs, commands, seed: sim.seed, ticks }
}

